    nuevas = [
        (f"{bandeja or 'Bandeja'} de 20", "BANDEJA", Decimal("0.666666")),  # 20 huevos = 2/3 de bandeja de 30
        (f"{caja or 'Caja'} Súper", "CAJA", Decimal("6")),                   # 9 bandejas de 20 = 180 huevos
    ]
    for nombre, formato, eq in nuevas:
        Presentacion.objects.get_or_create(nombre=nombre, defaults={
            "cantidad_bandejas_equivalentes": eq, "formato": formato, "huevos_por_bandeja": 20})


